def is_nested(string):
    # A valid subsequence with a nested bracket exists iff
    # there are indices i<j<k<l such that s[i]='[', s[j]='[', s[k]=']', s[l]=']'
    # i.e., the string contains "[[]]" as a subsequence.
    state = 0
    for ch in string:
        if state == 0 and ch == '[':
            state = 1
        elif state == 1 and ch == '[':
            state = 2
        elif state == 2 and ch == ']':
            state = 3
        elif state == 3 and ch == ']':
            return True
    return False
